Memory issue: Possible reference cycle with run_on_executor
Hi,
I've built a simple tornado server app and run on python 3.7.2 with tornado 6.0.1:
```
import tornado.ioloop
import tornado.web
import gc
import sys
from concurrent.futures.thread import ThreadPoolExecutor

from tornado import gen
from tornado.concurrent import run_on_executor

executor = ThreadPoolExecutor(1)


def dump_referrers(obj):
    print(sys.getrefcount(obj))
    for i in gc.get_referrers(obj):
        print('{} {}'.format(type(i).__name__, i))


class Test(object):
    def __init__(self):
        self.l = list(range(0, 100000))

    def __del__(self):
        print('del')


class Factory(object):
    _executor = executor

    @run_on_executor(executor='_executor')
    def run(self):
        test = Test()
        return test

factory = Factory()

class MainHandler(tornado.web.RequestHandler):

    def initialize(self):
        print('Init MainHandler')

    @gen.coroutine
    def get(self):
        test = yield factory.run()
        dump_referrers(test)
        self.write('data: {}'.format(test.l))
        self.finish()
        dump_referrers(test)


def make_app():
    return tornado.web.Application([
        (r"/", MainHandler),
    ])


if __name__ == "__main__":
    app = make_app()
    app.listen(8888)
    tornado.ioloop.IOLoop.current().start()
```

If I call the endpoint with `curl -i -X GET -H 'Content-Type: application/json' http://localhost:8888/`
I got the `del` text on the output of the server which means the ref count of `test` decreases to 0 and deleted by the system.
But If I call it more times. I don't have the `del` text anymore which means I guess there is a ref cycle which is will be deleted by the GC.

If I create a new `run_on_executor_asyncio` decorator and use the following code the test object always will be deleted.

```
import tornado.ioloop
import tornado.web
import gc
import sys
from concurrent.futures.thread import ThreadPoolExecutor
from tornado import gen
from tornado.concurrent import run_on_executor
import asyncio
import functools
from asyncio import Future
from typing import Callable, Any


def run_on_executor_asyncio(*args: Any, **kwargs: Any) -> Callable:
    def run_on_executor_decorator(fn: Callable) -> Callable[..., Future]:
        _executor = kwargs.get("executor", "executor")

        @functools.wraps(fn)
        def wrapper(self: Any, *args: Any, **kwargs: Any) -> Future:
            f = getattr(self, _executor).submit(fn, self, *args, **kwargs)
            return asyncio.wrap_future(f)

        return wrapper

    if args and kwargs:
        raise ValueError("cannot combine positional and keyword args")
    if len(args) == 1:
        return run_on_executor_decorator(args[0])
    elif len(args) != 0:
        raise ValueError("expected 1 argument, got %d", len(args))
    return run_on_executor_decorator



executor = ThreadPoolExecutor(1)


def dump_referrers(obj):
    print(sys.getrefcount(obj))
    for i in gc.get_referrers(obj):
        print('{} {}'.format(type(i).__name__, i))


class Test(object):
    def __init__(self):
        self.l = list(range(0, 100000))

    def __del__(self):
        print('del')


class Factory(object):
    _executor = executor

    @run_on_executor_asyncio(executor='_executor')
    def run(self):
        test = Test()
        return test

factory = Factory()

class MainHandler(tornado.web.RequestHandler):

    def initialize(self):
        print('Init MainHandler')

    @gen.coroutine
    def get(self):
        test = yield factory.run()
        dump_referrers(test)
        self.write('data: {}'.format(test.l))
        self.finish()
        dump_referrers(test)


def make_app():
    return tornado.web.Application([
        (r"/", MainHandler),
    ])


if __name__ == "__main__":
    app = make_app()
    app.listen(8888)
    tornado.ioloop.IOLoop.current().start()
```

I know that the ref cycles will be removed by GC but If I call that endpoint frequently the memory usage can go up more than 1GB before the GC starts. With the second version of code I can't go up to 100MB.

Is it possible that this is a bug in the `run_on_executor` decorator?

